import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Fidelity — dogfood-supabase-realtime-chat (v1.13-3)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/realtime/supabase-realtime-chat.md","filePath":"quality-reports/realtime/supabase-realtime-chat.md"}'),o={name:"quality-reports/realtime/supabase-realtime-chat.md"};function d(n,e,r,p,l,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="fidelity-—-dogfood-supabase-realtime-chat-v1-13-3" tabindex="-1">Fidelity — dogfood-supabase-realtime-chat (v1.13-3) <a class="header-anchor" href="#fidelity-—-dogfood-supabase-realtime-chat-v1-13-3" aria-label="Permalink to &quot;Fidelity — dogfood-supabase-realtime-chat (v1.13-3)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Supabase Realtime chat dogfood, produced by <code>examples/dogfood-supabase-realtime-chat/tests/emit-fidelity-report.test.ts</code>. Feeds <code>@kiwa/quality-metrics</code> 7-axis release gate.</p><h2 id="baseline-real-mode-skipped-—-no-supabase-url-supabase-anon-key" tabindex="-1">Baseline (real mode skipped — no <code>SUPABASE_URL</code> / <code>SUPABASE_ANON_KEY</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-supabase-url-supabase-anon-key" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`SUPABASE_URL\` / \`SUPABASE_ANON_KEY\`)&quot;">​</a></h2><p>When the harness runs without Supabase credentials, the real adapter emits <code>SUPABASE_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa/realtime/supabase-realtime-chat</span></span>
<span class="line"><span>version    : 0.1.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 4 (joinRoom / sendMessage / getPresence / sendTyping — recorded as BEHAVIORAL_DIVERGENCE, real mode absent)</span></span>
<span class="line"><span>axes       : 7 (common branch — realtime is not a token-priced generative surface)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (4/4)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>4.00 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>15</td><td>10</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts every op whose mock path succeeded but whose real path threw <code>SUPABASE_ENV_MISSING</code> — this is expected in a real-mode-skipped baseline and does not itself fail the gate (fidelity ratio measures the mock-covered surface area, which is 100% for the 4 ops the AC scopes).</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-supabase-realtime-chat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-supabase-realtime-chat/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real-mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SUPABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://your-project.supabase.co</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SUPABASE_ANON_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your-anon-key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-supabase-realtime-chat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When both env vars are set but <code>@supabase/supabase-js</code> is not vendored into the workspace (the default in this example), the adapter downgrades to <code>SUPABASE_SDK_MISSING</code> traces. Adding the dependency + wiring the connected paths in <code>src/adapters/real.ts</code> is a follow-up when a real Supabase project is provisioned — the adapter shape is ready.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Four provider-neutral ops on <code>ChatRoomAdapter</code>.</p><ul><li><code>joinRoom</code> — subscribe to a channel + track presence for a user</li><li><code>sendMessage</code> — broadcast a chat message on the channel</li><li><code>getPresence</code> — snapshot current room members</li><li><code>sendTyping</code> — broadcast typing events, debounced at 500 ms so mass keystrokes do not flood the channel</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>The mock engine (<code>packages/realtime/src/engine.ts</code>) tracks presence as <code>channel -&gt; Map&lt;userId, PresenceMember&gt;</code>, so multiple users joining the same room accumulate under a single channel subscription. Two-user tests drive both <code>joinRoom</code> calls through the same adapter to mirror how Supabase serves multiple clients over a shared connection.</p><p>The typing debounce is a client-side concern in the real Supabase SDK — this dogfood implements the same 500 ms window in <code>mock.ts</code> <code>sendTyping</code> so the fidelity harness can score the emitted / suppressed ratio as an observable behaviour, not a hidden implementation detail.</p><p>Provider prefix <code>@kiwa/realtime/</code> triggers the common 7-axis branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code>). The AI-LLM 4 axes (cost / latency / token / accuracy) do not apply because Supabase Realtime is a socket / pub-sub primitive, not a token-priced generative call. Socket round-trip latency feeds <code>perf.p95Ms</code> so realtime performance stays visible in the report.</p>`,19)])])}const m=a(o,[["render",d]]);export{u as __pageData,m as default};
